css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .sino-grid{display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px;}
.mz .sino-caja{border: 1.5px solid var(--bosque); border-radius: 8px; padding: 7px 8px 5px; display: flex; flex-direction: column; align-items: center; gap: 3px;}
.mz .sino-caja svg{width: 62px; height: 62px;}
.mz .sino-ops{font-family: sans-serif; font-weight: 700; font-size: 13px;}
.mz .ejes-grid{display: grid; grid-template-columns: repeat(4, 1fr); justify-items: center; align-items: center;}
.mz .ejes-grid svg{width: 70px; height: 70px;}
.mz .mitades{display: flex; justify-content: center; gap: 46px; padding-top: 2px;}
.mz .mitades svg{width: 136px; height: 136px;}
.mz .inventa{display: flex; justify-content: center; padding-top: 2px;}
.mz .inventa svg{width: 251px; height: 128px;}
.mz .vf-lista{display: flex; flex-direction: column; gap: 8px;}
.mz .vf-item{display: flex; align-items: center; justify-content: space-between; gap: 10px; font-size: 13px; border-bottom: 1px dotted #999; padding-bottom: 4px;}
.mz .vf-opciones{font-family: sans-serif; font-weight: 700; font-size: 12.5px; white-space: nowrap;}
